insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('0622f4df-fb1f-5ef1-8590-72ed16a29659', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text with the most logical and precise word or phrase?', '["elevated from", "surpassed by", "differentiated from", "explored by"]'::jsonb, 1, 'Blue holes, such as the Great Blue Hole and Watling’s Blue Hole, are deep sinkholes that form underwater. Because the dark blue appearance of their waters means these pits can be easily ______ shallow areas around them, where the water looks light blue, many blue holes have been discovered by people doing recreational activities like boating.'),
  ('98556a5a-417d-58b3-8809-5823a81deb04', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text with the most logical and precise word or phrase?', '["interpret", "overshadow", "hasten", "transform"]'::jsonb, 2, 'By eliminating middlemen, direct-to-consumer sales channels allow small farms to capture retail prices rather than accept lower wholesale rates. The pricing advantages that come with adopting this model, combined with the customer loyalty that comes from forging personal connections, can ______ the financial outlook for many small agricultural producers.'),
  ('6b0a8735-304d-5c4c-87b7-303defae1311', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text with the most logical and precise word or phrase?', '["reprimanded", "adhered to", "awarded", "refrained from"]'::jsonb, 3, 'Tabby Cat is an important work of Nihonga, or classical Japanese painting. Unlike Saeki Yūzō, who adopted traditional European methods such as painting with oil on canvas, Takeuchi Seihō ______ traditional Japanese approaches. For instance, Takeuchi produced Tabby Cat by applying color pigments to a silk surface.'),
  ('8a439dbc-959c-5d0a-98ad-1842dd054230', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text with the most logical and precise word or phrase?', '["indicative of", "incongruous with", "subordinate to", "opportune for"]'::jsonb, 4, 'The swordfish is an ectothermic (cold-blooded) fish, whereas the southern bluefin tuna is a regional endotherm; unlike that of ectotherms, its body temperature remains above the ambient water temperature. The basking shark had been classified as a full ectotherm, but researchers Haley R. Dolton et al. found that its body temperature remains 1.0 to 1.5°C above ambient, which is ______ that classification.'),
  ('55368455-550b-50ab-a0cf-7ddfe3761d67', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text with the most logical and precise word or phrase?', '["discrepancy", "insolvency", "redundancy", "vulnerability"]'::jsonb, 5, 'A variety of technologies make use of magnets incorporating rare earth elements, such as gadolinium. For technology manufacturers, dependence on rare earth elements is a significant ______. Such elements are extracted at large scale in only a small number of locations, making any supply chain requiring them highly fragile.'),
  ('39925218-e600-5773-b84c-e2b67e5d07e8', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text with the most logical and precise word or phrase?', '["supplement", "supersede", "replicate", "complicate"]'::jsonb, 6, 'The presumptive functionality of khipu, the semiotic system of knotted cords once used by Indigenous Andean peoples, to encode language (perhaps, like ancient Chinese script, in units of discrete words) now has an empirical basis: Manuel Medrano’s statistical data on Spanish translations of khipu content, as recited by Aymara-speaking scribes, ______ historical reports of khipu’s status as a linguistic record.'),
  ('4965da71-500f-5fec-8d12-4e395fb129c1', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice best describes the overall structure of the text?', '["It discusses some characteristics of cones in human eyes and then discusses a study involving those cones.", "It explains what the color olo is and then explains how that color was discovered.", "It mentions three different colors and then mentions the wavelengths associated with those colors.", "It names different cells in human eyes and then states how they work with cells in a different part of the body."]'::jsonb, 7, 'Human eyes contain cone cells that help process color and bright light. There are three types of cones: long, medium, and short. In a study, James Fong and his team used a laser technology to activate only the medium cones in participants’ eyes. When they did this, the participants saw a new blue-green color that the researchers then named olo.'),
  ('959d5bdc-8e77-5500-98ea-1ad32c25bb22', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice best states the function of the underlined portion in the text as a whole?', '["It provides evidence for the text’s claim that the Lindy Hop has had a greater cultural impact than the other dances featured in The Jazz Continuum have had.", "It identifies the specific ways in which the Lindy Hop is similar to the contemporary dance styles discussed in the text.", "It addresses the reasons why the historical connections between the dance styles mentioned earlier in the text have been generally overlooked.", "It identifies the motivation for The Jazz Continuum’s choreographic approach that is described earlier in the text."]'::jsonb, 8, 'In The Jazz Continuum, LaTasha Barnes, Imani Arrington, and other dancers seamlessly interweave recent dance styles, including hip-hop and waacking, with elements of the Lindy Hop, a popular swing dance of the 1930s with roots in the Black American community of Harlem, New York. <u>Inspired by Barnes’s</u> <u>curiosity about the similarities between the Lindy Hop and these seemingly unrelated dance styles</u>, the show’s choreography makes visible how intertwined their histories actually are. The show is therefore a testament to the Lindy Hop’s enduring influence on American culture.'),
  ('21a30017-e3fa-5c18-b8a7-9c96904d1b4f', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice best states the function of the underlined portion in the text as a whole?', '["It identifies the specific ways in which the Lindy Hop is similar to the contemporary dance styles discussed in the text.", "It identifies the motivation for The Jazz Continuum’s choreographic approach that is described earlier in the text.", "It provides evidence for the text’s claim that the Lindy Hop has had a greater cultural impact than the other dances featured in The Jazz Continuum have had.", "It addresses the reasons why the historical connections between the dance styles mentioned earlier in the text have been generally overlooked."]'::jsonb, 9, 'In The Jazz Continuum, LaTasha Barnes, Tyedric Hill, and other dancers seamlessly interweave recent dance styles, including hip-hop and voguing, with elements of the Lindy Hop, a popular swing dance of the 1930s with roots in the Black American community of Harlem, New York. <u>Inspired by Barnes’s curiosity</u> <u>about the similarities between the Lindy Hop and these seemingly unrelated dance styles</u>, the show’s choreography makes visible how intertwined their histories actually are. The show is therefore a testament to the Lindy Hop’s enduring influence on American culture.'),
  ('2d95570c-8845-5015-9e0d-694b1cda7ec3', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice best states the main purpose of the text?', '["To describe the importance of intellectual humility to scientists", "To explain how a specific project fosters intellectual humility", "To cite specific examples of scientists who acknowledged flaws in their work", "To identify a particular mistake made by scientists in a research project"]'::jsonb, 10, 'Some psychologists such as Julia Rohrer are conducting projects that are meant to foster intellectual humility (the ability to realize that one is wrong and to publicly admit it) among scientific researchers. This is important: the scientific process is ideally self-correcting as new research either confirms or contradicts prior findings, but that process is slowed when researchers are unwilling to acknowledge that disputed work of theirs might have flaws. If embraced by scientists, intellectual humility therefore has the potential to increase the efficiency of scientific research.'),
  ('b5b8e779-feea-5959-91a8-78a2892db028', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Based on the texts, how would Rose and colleagues (Text 2) most likely respond to the assertion by Slater and Mann (Text 1) about the different prevalence of female birdsong in temperate and tropical areas?', '["They would argue that the apparent difference in prevalence may partly reflect a difference in the ease with which female birdsong and male birdsong can be detected.", "They would concede that the geographic difference in prevalence is real but argue that the frequency with which male tropical birds sing has been overstated by previous researchers.", "They would raise the possibility that the difference in prevalence may be due to differences in the timing of the mating season among temperate and tropical bird species.", "They would caution that the seeming difference in prevalence may be an artifact of researchers’ tendency to study birdsong among temperate species more frequently than among tropical species."]'::jsonb, 11, '**Text 1**

For decades, ornithologists assumed that if they saw a singing Cassin’s finch—a bird species found in temperate North America—they must be observing a male trying to attract a mate or claim territory. As Peter J.B. Slater and Nigel I. Mann have emphasized, however, a similar assumption can’t be made about birds in the tropics, where females sing as often as males do. Slater and Mann call for more research on this discrepancy between tropical and temperate female birdsong.

**Text 2**

Recent evidence shows that a female Cassin’s finch is as capable of song as a male is. In fact, female birdsong is more common among temperate species than currently assumed, claim Evangeline Rose and colleagues. These female songbirds sing less frequently than males do, and in duller tones, making it “easy for researchers to miss the quiet and hidden females and focus on the loud and colorful males,” says Rose.'),
  ('922a8250-84c5-5753-9ccc-f0d005cbafc3', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Based on the texts, the author of Text 2 would most likely agree with which statement about the “principle” mentioned in Text 1?', '["It has been challenged by some studies, but the findings of those studies have not been widely accepted.", "It may be true for some predators but only because those predators share certain physical characteristics.", "It has some evidential support, but it should not be regarded as universally applicable.", "It is plausible, but many of the studies that support it have methodological flaws."]'::jsonb, 12, '**Text 1**

In parts of Finland, the least weasel is a major predator of the field vole. Researcher Tero Klemola and colleagues found that when this predation pressure on field voles was temporarily reduced, their numbers significantly increased. This finding illustrates a foundational ecological principle: predators control prey population numbers.

**Text 2**

Michel Crête and Hélène Jolicoeur found that excluding wolves from a site in Quebec, Canada, where they typically prey on moose had no significant effect on moose abundance. Many other predation relief studies show an increase in prey abundance, but those studies often focus on small, rapidly reproducing prey, like birds, voles, and rabbits, rather than large, slowly reproducing prey, like moose, which could account for the difference between those results and Crête and Jolicoeur’s results.'),
  ('2e3995a0-a586-59e6-9896-5a166f119cbb', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'In context, the text’s characterization of the biodiversity in city parks as “hidden” most clearly conveys which idea?', '["There are many beautiful parks in cities, but they often remain unseen because of poor urban planning decisions.", "The environmental interactions in city parks are abundant but occur primarily during nighttime hours when human visitors are absent.", "The ecological relationships in city parks may not be readily apparent without systematic observation and documentation efforts.", "Some wildlife species that populate city parks have developed sophisticated camouflage techniques that minimize their visibility."]'::jsonb, 13, 'While not everyone notices it, beneath the tree canopy of an ordinary city park lies an extraordinary web of life—fungi breaking down fallen leaves, native bees pollinating wildflowers, and moss growing in the crevices of an old log. To document this hidden biodiversity, everyday people have been participating in “BioBlitz” events, in which participants photograph, collect, and identify species using both field guides and mobile apps. These collective observations reveal which plant and animal species depend on one another for survival—ecological relationships that might otherwise remain unseen.'),
  ('63a38f28-4994-5b22-998a-b4aa0c516be5', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which statement about Uman’s art is most strongly supported by the text?', '["Its rejection of established aesthetic criteria can be traced to Uman’s ambivalence toward cultural traditions.", "Its adherence to certain dichotomies sets it apart from the work of most abstract artists based in the United States.", "Its openness to experimentation is evident in its diverse influences and refusal to adhere to a single conceptual frame.", "Its spontaneity makes it challenging for critics to recognize the conventions of genre that Uman chooses to observe."]'::jsonb, 14, 'New York-based artist Uman is no stranger to crossing borders: born in Somalia, she lived in Kenya and Denmark before moving to the United States. Her art, too, straddles multiple boundaries. Drawing on knowledge of everything from East African fabrics to Arabic calligraphy, Uman’s kaleidoscopic paintings often combine abstract shapes with anthropomorphic elements, like eyes, mouths, and gestures. Moreover, she seeks to cultivate a practice of “constant evolution” untethered from any prescriptive agenda, so that her art navigates a liminal space between tradition and autobiography, community and itinerancy, and activism and contemplation.'),
  ('5404a96d-0738-5daa-a0a4-23ccc9867197', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice most effectively uses data from the table to complete the statement?', '["Switzerland.", "India.", "the United States.", "Kenya."]'::jsonb, 15, '**Corporate Tax Complexity Index for Four Countries, 2022**

| Country | Tax Complexity Index |
| India | 0.42 |
| Kenya | 0.37 |
| Switzerland | 0.23 |
| United States | 0.40 |

Every two years from 2016 to 2022, the research project Accounting for Transparency has conducted a worldwide survey of tax consultants and tax services firms in order to calculate the Tax Complexity Index, a measure of the complexity of a nation’s corporate income tax system. The index ranges from zero (minimally complex) to one (extremely complex). In the table, the country with the simplest corporate tax system in 2022 was ______.'),
  ('fcdbbd90-580c-557d-8528-37f3b3a82cd7', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Based on the text, why was the sleight-of-hand step an important part of the experiment?', '["It allowed the researchers to control for the possibility that some participants found the two faces roughly equally attractive.", "It helped the researchers test whether participants would embrace an outcome they thought was consistent with their intention even when it was truly contradictory.", "It enabled the researchers to determine whether the thought process involved in selecting which photo had the more attractive face was similar to the thought process involved in selecting a preferred jam.", "It allowed the researchers to measure the willingness of participants to change their positions when presented with persuasive counterarguments."]'::jsonb, 16, 'In 2005, Swedish researchers studying flawed choice recall devised an experiment in which participants were shown two photos of different faces and asked to select the one they found more attractive. The researchers appeared to give the participants the photo they had chosen, but in fact used sleight of hand to give them the photo of the person they had not chosen. Most participants accepted the swap and, when asked to explain their initial preference, gave justifications for having chosen the face in the photo they were given. Subsequent researchers have replicated this finding with other choices, including jam preferences.'),
  ('3117cae6-e23d-5d57-9b18-afaa256bf2bf', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["provided", "providing", "to provide", "having provided"]'::jsonb, 17, 'Archaeological investigations of ancient Maya wetland agriculture in Belize have revealed extensive networks of ditches and drainage canals. These complex raised-field systems, constructed by excavating channels through flood-prone bogs to create elevated planting platforms, ______ substantial agricultural surplus during periods of severe population density.'),
  ('b1ad04f9-52d8-559d-adf7-f46bf856209d', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["the Petén LiDAR initiative revealed", "previously unrecorded structures were discovered by researchers with", "the discovery of fortifications was made by archaeologists in", "domestic terraces and causeways were documented through"]'::jsonb, 18, 'Employing high-precision laser altimetry to map the dense canopy of the Guatemalan jungle, ______ of previously unrecorded structures, including fortified hilltop defenses, interconnected causeways, and domestic residential terraces.'),
  ('b786ff2e-32af-5c51-bd50-95ebf0c2dfad', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["should they open?", "they should open.", "should they open.", "they should open?"]'::jsonb, 19, 'When conducting remote sensing surveys of ancient architectural complexes, archaeological teams must evaluate spatial patterns in multi-spectral imagery before deciding which excavation trench ______'),
  ('65b6cd63-ca2d-53b2-b4ed-8c061033d407', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Picasso;", "Picasso—", "Picasso:", "Picasso,"]'::jsonb, 20, 'The 1913 Armory Show in New York City introduced American audiences to European modernism—including radical works by Marcel Duchamp, Henri Matisse, and Pablo ______ forever altering the trajectory of American twentieth-century art.'),
  ('d11dedd1-a2e2-5321-8124-368f41dbdf08', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["efficiency", "efficiency.", "efficiency;", "efficiency, but"]'::jsonb, 21, 'In materials science, perovskite solar cells have gained considerable attention for their remarkable power-conversion ______ unlike traditional silicon photovoltaic panels that require high-temperature manufacturing, perovskite crystallites can be processed from inexpensive chemical solutions at relatively low temperatures.'),
  ('15573527-5f5d-5402-83d2-74b4c7bac1d4', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text with the most logical transition?', '["In contrast,", "For instance,", "As a result,", "Furthermore,"]'::jsonb, 22, 'Geothermal power plants utilize steam extracted from subterranean reservoirs to turn turbines and produce electricity. In Iceland, volcanic geology provides an exceptionally shallow geothermal resource, allowing geothermal energy to supply over 25% of the country’s primary energy needs. ______ in regions lacking active tectonic boundaries, drilling deep enough to access equivalent subterranean heat is often economically prohibitive.'),
  ('89579ba2-a6f8-57da-9513-945e1432b2f5', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text with the most logical transition?', '["therefore,", "nevertheless,", "indeed,", "conversely,"]'::jsonb, 23, 'Tardigrades are microscopic invertebrates celebrated for their ability to survive lethal extremes of temperature, radiation, and dehydration by entering a dormant state known as anhydrobiosis. In this desiccation-tolerant state, the animals suspend all metabolic processes and synthesize specialized disordered proteins to protect cellular membranes. When rehydrated, ______ tardigrades resume active cellular respiration and locomotion within several hours.'),
  ('ce6d4021-84c2-558a-869d-9bbb60260034', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice completes the text with the most logical transition?', '["Indeed,", "Similarly,", "In many cases,", "Therefore,"]'::jsonb, 24, 'Every US state has an associated state soil, which is typically selected by a group of experts, then passed through the state legislature to receive its official designation. For example, South Dakota’s Houdek soil was formally designated in 1990, and Maine’s Chesuncook soil in 1999. ______ years pass between a soil’s selection and official designation, as the legislative process can be notoriously slow.'),
  ('707cdcb8-dfa3-58c2-941f-16c64055fa07', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'Which choice most effectively uses information from the given sentences to emphasize the different years in which the books reached the NYT Best Sellers list?', '["Between the World and Me and Roots: The Saga of an American Family are both books by Black authors that have reached the NYT Best Sellers list.", "Ta-Nehisi Coates and Alex Haley are both NYT best-selling authors.", "The novel Roots: The Saga of an American Family became an NYT best seller in 1976; Between the World and Me, a nonfiction book, joined this list as well, but in 2015.", "Ta-Nehisi Coates’s Between the World and Me and Alex Haley’s Roots: The Saga of an American Family are both NYT best sellers, but the former is a nonfiction book whereas the latter is a novel."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:
Since 1931, the New York Times (NYT) Best Sellers list has been a measure of the most successful books in the US.
Ta-Nehisi Coates and Alex Haley are Black authors who have reached the NYT Best Sellers list. Between the World and Me is a nonfiction book by Ta-Nehisi Coates. It reached the NYT Best Sellers list on August 2, 2015.
Roots: The Saga of an American Family is a novel by Alex Haley. It reached the NYT Best Sellers list on August 17, 1976.'),
  ('c14b6872-8533-5e06-bdfd-c308eb68fc9e', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'The student wants to explain how the kingfisher’s beak was used to solve the bullet train’s sonic boom problem. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Nakatsu’s observation of kingfishers diving into water showed how the bird’s beak structure could help the train eliminate sonic booms.", "The shape of the kingfisher’s beak inspired engineers to reshape the train nose into one that gradually widens, allowing the train to move smoothly between air and water.", "By redesigning the train’s nose to imitate the kingfisher’s gradually widening beak shape, engineers improved the train’s transition between tunnels and open air, eliminating sonic booms.", "Nakatsu discovered that the kingfisher’s beak structure eliminated sonic booms, and the redesign improved the train’s transition between tunnel and open-air environments."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

The Shinkansen (bullet train) is a network of high-speed railways in Japan.
1960s: The trains’ high speeds created intense pressure waves that produced sonic booms when trains exited tunnels.
1980s: Engineer Eiji Nakatsu noted that the kingfisher bird could dive into water at high speeds while barely creating a splash.
The kingfisher’s beak gradually widens from tip to head, allowing smooth transition between air and water.
Nakatsu and other engineers redesigned the train nose based on the kingfisher’s beak structure to improve the transition between tunnel and open-air environments.
The redesign reduced pressure buildup, eliminating sonic booms.'),
  ('c9ac46bc-6e71-5024-860f-12fb0fb9bfa7', '30bc1249-bf61-56c1-a5ad-578ad1c632dc', 'The student wants to emphasize a difference between the two lighthouse keepers. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["From 1863 to 1881, the nighttime waters of Maryland were made more navigable thanks to Esther O’Neill.", "As the lighthouse keeper at Turkey Point Light, Fannie May Salter helped watercraft navigate at night.", "Esther O’Neill worked as a lighthouse keeper in an earlier century than did Fannie May Salter.", "Esther O’Neill and Fannie May Salter both played crucial roles in ensuring safe navigation for watercraft in past centuries."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Lighthouses send out crucial light signals to help ships and other watercraft navigate at night. Before automation, lighthouses were run by lighthouse keepers.
Esther O’Neill was the lighthouse keeper at Concord Point Light in Maryland, from 1863 to 1881. Fannie May Salter was the lighthouse keeper at Turkey Point Light in Maryland, from 1925 to 1947.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('0622f4df-fb1f-5ef1-8590-72ed16a29659', 2, null, 'The dark blue water makes the holes easy to tell apart from the light blue shallows, so "differentiated from" fits.'),
  ('98556a5a-417d-58b3-8809-5823a81deb04', 3, null, 'Better prices plus customer loyalty can greatly change (improve) the farms'' finances: "transform."'),
  ('6b0a8735-304d-5c4c-87b7-303defae1311', 1, null, 'Unlike Saeki, who used European methods, Takeuchi kept to Japanese ones (pigments on silk): "adhered to."'),
  ('8a439dbc-959c-5d0a-98ad-1842dd054230', 1, null, 'A body temperature above ambient does not fit the label "full ectotherm," so the finding is "incongruous with" it.'),
  ('55368455-550b-50ab-a0cf-7ddfe3761d67', 3, null, 'Supply comes from only a few places, so the chain is fragile: dependence is a "vulnerability."'),
  ('39925218-e600-5773-b84c-e2b67e5d07e8', 0, null, 'The statistical data add empirical support to the historical reports: they "supplement" them.'),
  ('4965da71-500f-5fec-8d12-4e395fb129c1', 0, null, 'The text first describes cone cells, then a study (Fong''s laser experiment) involving those cones.'),
  ('959d5bdc-8e77-5500-98ea-1ad32c25bb22', 3, null, 'The underlined phrase says what inspired the choreography described just before it.'),
  ('21a30017-e3fa-5c18-b8a7-9c96904d1b4f', 1, null, 'The underlined phrase gives the motivation (Barnes''s curiosity) for the show''s choreographic approach.'),
  ('2d95570c-8845-5015-9e0d-694b1cda7ec3', 0, null, 'The text explains why intellectual humility matters for scientific research.'),
  ('b5b8e779-feea-5959-91a8-78a2892db028', 0, null, 'Rose says quiet, dull-toned females are easy to miss, so the apparent difference may come from how easily songs are detected.'),
  ('922a8250-84c5-5753-9ccc-f0d005cbafc3', 2, null, 'Text 2 shows the principle holds for small, fast-breeding prey but not for moose, so it is not universal.'),
  ('2e3995a0-a586-59e6-9896-5a166f119cbb', 2, null, '"Hidden" refers to relationships that "might otherwise remain unseen" without the BioBlitz observations.'),
  ('63a38f28-4994-5b22-998a-b4aa0c516be5', 2, null, 'Diverse influences and "constant evolution untethered from any prescriptive agenda" show openness and no single frame.'),
  ('5404a96d-0738-5daa-a0a4-23ccc9867197', 0, null, 'The lowest index (simplest system) is Switzerland, 0.23.'),
  ('fcdbbd90-580c-557d-8528-37f3b3a82cd7', 1, null, 'The swap tested whether people would accept and justify a result that actually contradicted their choice.'),
  ('3117cae6-e23d-5d57-9b18-afaa256bf2bf', 0, null, 'The subject "systems" needs a finite main verb: "provided."'),
  ('b1ad04f9-52d8-559d-adf7-f46bf856209d', 0, null, 'The opening modifier describes who used the laser altimetry, so the subject must be the initiative that did it.'),
  ('b786ff2e-32af-5c51-bd50-95ebf0c2dfad', 1, null, 'An indirect question is a statement: subject before verb and a period.'),
  ('65b6cd63-ca2d-53b2-b4ed-8c061033d407', 1, null, 'The aside begins with a dash after "modernism," so it must close with a dash.'),
  ('d11dedd1-a2e2-5321-8124-368f41dbdf08', 2, null, 'Two independent clauses ("unlike..." starts with a lowercase letter) are joined with a semicolon.'),
  ('15573527-5f5d-5402-83d2-74b4c7bac1d4', 0, null, 'Iceland''s shallow resource contrasts with regions where deep drilling is too costly.'),
  ('89579ba2-a6f8-57da-9513-945e1432b2f5', 3, null, 'The dormant state (metabolism suspended) is the opposite of the rehydrated state (metabolism resumes): "conversely."'),
  ('ce6d4021-84c2-558a-869d-9bbb60260034', 2, null, 'The examples show the years-long gap often happens, not always: "In many cases."'),
  ('707cdcb8-dfa3-58c2-941f-16c64055fa07', 2, null, 'Only this choice states both years, 1976 and 2015.'),
  ('c14b6872-8533-5e06-bdfd-c308eb68fc9e', 2, null, 'It links the beak''s widening shape to the redesigned nose and the end of sonic booms.'),
  ('c9ac46bc-6e71-5024-860f-12fb0fb9bfa7', 2, null, 'It contrasts when each keeper worked: the 1800s vs the 1900s.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

