insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('43240bcc-7c2a-5df7-96a7-faaf573219c4', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text with the most logical and precise word or phrase?', '["imperceptible", "invariable", "malicious", "ambiguous"]'::jsonb, 1, 'Software that automatically detects suspicious behavior on computer networks has become so sensitive that much of the activity it detects is ______, which means that rather than replacing human experts, such software has increased the need for cybersecurity specialists to interpret the flagged activity and determine whether it is a cause for concern.'),
  ('8266c14f-5ac9-59aa-a8a8-c2bf2c1d6167', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text with the most logical and precise word or phrase?', '["detangling", "evacuating", "designating", "bracing"]'::jsonb, 2, 'The longevity of heating and cooling systems depends significantly on technicians properly ______ refrigerant lines during installation. If non-condensable gases, moisture, and microscopic debris aren’t purged from the lines, vital components can be damaged during use, leading to total system failure.'),
  ('fe610683-8f5f-5106-bef1-6266aa4bd6be', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text with the most logical and precise word or phrase?', '["entitled", "prone", "loath", "admonished"]'::jsonb, 3, 'Although the cumulative weight of the goods in a cargo truck affects fuel efficiency, this effect—and the corresponding effect on the cost of a given trip to the trucking company—is relatively small. The large majority of a trip’s cost stems from the mere fact of the truck being on the road; accordingly, trucking firms are ______ to dispatch trucks that aren’t full.'),
  ('ae4492d4-19e1-599c-847c-901a4ba67526', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text with the most logical and precise word or phrase?', '["unresponsive", "detrimental", "pertinent", "amenable"]'::jsonb, 4, 'Though research indicating that plants may preferentially absorb nickel and other essential elements (i.e., those necessary for plant growth) from soil over nonessential ones seems to suggest that nickel-contaminated soil may be especially ______ to decontamination by plants, Stephan Pauleit and team found that plants tended to accumulate the nonessential element cadmium at higher rates than nickel; the presence of cadmium in such soils should thus be assessed before pursuing plant-based nickel decontamination.'),
  ('d0c9db1b-2a5a-5e4a-904f-a493983f3d5e', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text with the most logical and precise word or phrase?', '["amenable", "unresponsive", "pertinent", "detrimental"]'::jsonb, 5, 'Though research indicating that plants may preferentially absorb nickel and other essential elements (i.e., those necessary for plant growth) from soil over nonessential ones seems to suggest that nickel-contaminated soil may be especially ______ to decontamination by plants, Swantje Duthweiler and team found that plants tended to accumulate the nonessential element cadmium at higher rates than nickel; the presence of cadmium in such soils should thus be assessed before pursuing plant-based nickel decontamination.'),
  ('6da77714-8783-5338-8502-c7da9829bad6', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice best describes the function of the underlined portion in the text as a whole?', '["It suggests an advantage that microwave heating has over conventional thermal processing methods.", "It identifies a flaw of microwave heating technologies.", "It introduces microwave heating as a food processing technology.", "It explains why conventional thermal processing methods are popular in commercial applications."]'::jsonb, 6, 'Microwave heating, a thermal technology used to preserve food on an industrial scale, is generally considered to be an improvement over more conventional thermal preservation methods. Scientists in Latin America have contributed to a better understanding of this technology, with researchers from Mexico demonstrating its effectiveness in preserving mamey sapote fruits. As research continues, scientists hope to make advancements in hybrid systems combining multiple food preservation technologies, which would be advantageous over using microwave heating alone, <u>given that it often</u> <u>heats food unevenly</u>.'),
  ('131e6aa5-7af8-54ff-a0a0-7d7cbc9bf5ef', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice best describes the overall structure of the text?', '["It identifies several positive emotions and then asserts that positive expressive writing should be done daily to amplify those emotions.", "It gives an overview of positive expressive writing and then states a research finding about this type of writing.", "It introduces a study about positive expressive writing and then explains that the researchers are planning a follow-up study.", "It describes one popular technique of positive expressive writing and then names the techniques researchers have found to be most useful."]'::jsonb, 7, 'Positive expressive writing is self-reflective writing aimed at exploring positive topics and feelings like joy. Techniques of positive expressive writing include one called “benefit finding,” which involves writing about positives that come from difficult experiences, and “satisfaction processes,” which involves writing in-depth about how certain experiences lead to feelings of fulfillment. In a large-scale analysis, Lauren Hoult and colleagues determined that while different techniques produce varying outcomes, they all tend to have a more consistent effect on well-being and positive outlook than on physical health and stress.'),
  ('fd761735-fdc6-515f-9ead-9a5a353bfe47', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice best describes a notable difference in focus between Text 1 and Text 2?', '["Both texts establish that people need to be made aware of the specific ways global issues are likely to affect them individually, but Text 1 focuses on the empathy those details inspire and Text 2 focuses on the obligation those details entail.", "Both texts suggest that embracing commonalities can be beneficial when it comes to urging people to collective action to address global issues, but Text 1 focuses on the broadest scope of connection and Text 2 focuses on connections more limited in scope.", "Both texts imply that global issues are equally relevant to all people living today, but Text 1 focuses on the idea that such issues will remain broadly relevant for the foreseeable future and Text 2 focuses on the idea that certain issues may soon become less relevant.", "Both texts indicate that global issues should be addressed with large-scale shared efforts, but Text 1 focuses on the idea that it may be most effective to link global and local coordination and Text 2 focuses on the idea that local efforts sometimes divert attention from broader coordination."]'::jsonb, 8, '**Text 1**

It’s clear that worldwide cooperation is needed to tackle global issues such as climate change. However, it hasn’t been clear how to foster strong group cohesion to motivate prosocial behavior at a global level given that humans tend to align more locally, from family to nationality. Evidence now shows that being prompted to consider the shared biology of all humans can cause individuals to identify more strongly with humanity overall, suggesting that emphasis on the “global family tree” may promote collective action.

**Text 2**

Perhaps counterintuitively, a focus on group distinctions can help ensure that responsibility for issues with global effects (e.g., natural resource depletion and climate change) is shared globally. For example, though young people don’t always view themselves as essential parties in such matters, reminders of their collective role as future inheritors of problems left unsolved can spark their engagement.'),
  ('fb2e03a0-bfc6-5beb-88f2-5ef721bbc2e8', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'According to the text, which factors seemed to be linked to the behavior of butterflies in Grace Herzel and colleagues’ study?', '["Neither butterfly color nor weather conditions", "Both butterfly color and weather conditions", "Weather conditions but not butterfly color", "Butterfly color but not weather conditions"]'::jsonb, 9, 'Biologist Grace Herzel and colleagues conducted a study of how butterfly color and weather conditions relate to butterfly behavior, which wouldn’t have been possible without data gathered by students and other amateur science enthusiasts in the community. Considering over three years’ worth of data, the researchers found that white butterflies were observed on green flowers more often than any other butterflies were, and that butterflies were observed to feed more often on cloudy days than on other days.'),
  ('8d15134e-6b62-5234-8b48-719bfb0bb66d', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Based on the information given, which choice most effectively uses data from the table to complete the student’s conclusion?', '["shows evidence of increasing continental crust material in later-forming minerals.", "8786\ndoes not show the expected Sr/Sr ratios across the stages of mineral formation.", "8786\ncontains Sr/Sr ratios too similar to provide reliable information about magma sources.", "formed from magma with decreasing but persistent crustal influence."]'::jsonb, 10, '**Strontium Isotope Ratios for an Igneous Rock Sample**

| Mineral Zone | 8786 Sr/Sr Ratio |
| Crystal core | 0.71685 |
| Crystal rim | 0.71548 |
| Crystal matrix | 0.71416 |

A student is studying igneous rock formations on Elba Island, Italy, and reviews published data on the 8786
ratio of strontium isotopes (Sr/Sr) in minerals from a specific rock sample. These isotope ratios provide information about the composition of the magma that formed the rock. Ratios below 0.710 suggest more material from the mantle in the magma, while ratios increasing above that number usually indicate greater proportions of material from the continental crust. The minerals in the rock sample record three growth stages: crystal core zones formed first, then rim zones, and finally the surrounding matrix. The student concludes that the rock sample ______.'),
  ('0a56af3a-5e91-5383-a32b-10317d7a62dc', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice most effectively uses data from the table to complete the statement?', '["4:30–7:30 p.m. for previously restricted roads.", "10:00 a.m.–4:30 p.m. for previously unrestricted roads.", "7:00–10:00 a.m. for both types of roads.", "7:00–8:00 p.m. for both types of roads."]'::jsonb, 11, '**Change in Average Traffic Delay After End of Restriction (min/km)**

| Time Period | Previously Restricted | Previously Unrestricted |
| 6:00–7:00 a.m. | 0.00 | 0.03 |
| 7:00–10:00 a.m. | 0.98 | 0.13 |
| 10:00 a.m.–4:30 p.m. | 0.55 | 0.71 |
| 4:30–7:00 p.m. | 2.48 | 0.60 |
| 7:00–8:00 p.m. | 1.98 | 1.32 |
| 8:00 p.m.–6:00 a.m. | 0.05 | 0.16 |

In 2016, the city of Jakarta—one of the world’s largest metropolitan areas—revoked a rule that restricted the use of major roads in the city’s business district to only vehicles with three or more passengers during rush hours (7:00–10:00 a.m. and 4:30–7:00 p.m.). As researchers had expected, this move led to increased traffic delays during those times on the roads whose use had been limited, especially in the later rush hour period. Surprisingly, delays also worsened during other periods of time and on roads that hadn’t been subject to the rule; the data most clearly reflect this effect in the period of ______.'),
  ('72e3f2ef-053c-52de-9a9a-b2d22bb7e20d', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which finding, if true, would most directly explain why Wasef and colleagues reject the common explanation presented in the text?', '["The continent-wide population structure of modern dingoes matches that of the dingoes that were present in Australia around 2,000 years ago.", "Ancient dingoes quickly dispersed throughout Australia after being introduced in two independent waves from distinct source populations at least 3,000 years ago.", "The two earliest known sets of skeletal dingo remains in Australia date to around 3,400 years ago at a site in the west and around 3,300 years ago at a site in the east.", "New Guinea singing dogs, a closely related species, began interbreeding with dingoes in southeast Australia 2,200–2,600 years ago and with dingoes in northwest Australia in the same period."]'::jsonb, 12, 'Australia’s modern population of dingoes, an ancient lineage of canids, comprises two genetically distinct groups that inhabit different sides of the country (west and east). Many have attributed this divergence to the nearly 3,500-mile-long “dingo fence,” a barrier installed to prevent access to livestock, that created a division of Australia into large southeast and northwest sections around 150 years ago. However, having analyzed DNA from ancient dingo specimens ranging from hundreds to thousands of years old, paleogeneticist Sally Wasef and colleagues reject that common explanation.'),
  ('4816b15a-d7a9-5fb9-abb2-0a63bc3c7e0d', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Based on the information in the text, Tarhan et al. could most reasonably draw which conclusion?', '["The range of Ge/Si ratios is larger for the cements than for the grains, which suggests that the cements are likely the result of high-pressure reactions that occurred long after the organisms were preserved by some other means than precipitation from a silica-rich ocean.", "The distribution of Ge/Si ratios indicates that a portion of the cements could have precipitated via high-pressure reactions, which suggests that organisms at the site were less likely to have been preserved via rapid precipitation from a silica-rich ocean than Tarhan et al. hypothesized.", "The distribution of Ge/Si ratios of the cements and grains is largely inconsistent with the cements having precipitated via high-pressure reactions, which implicitly lends support to the idea that the organisms at the site were quickly preserved by cement precipitation from a silica-rich ocean.", "The total number of cement samples is much lower than the total number of grains precipitated via high-pressure reactions, which suggests that rapid precipitation from silica-rich oceans could account for the preservation of the site’s organisms."]'::jsonb, 13, 'Silica cements associated with casts of soft-bodied marine organisms from the Ediacaran period (circa 538–635 million years ago) are plausibly attributable to one of two phenomena: rapid postmortem preservation of the organisms via precipitation of cements from silica-rich oceans or cement precipitation via high-pressure reactions long after the organisms were preserved by some other means. Recognizing that such reactions generally result in cements with germanium/silicon (Ge/Si) ratios lower than those of silica grains recovered from the same portion of sandstone, Lidya Tarhan et al. investigated silica cements and grains associated with Ediacaran soft-bodied casts at a site in South Australia.'),
  ('d40da08f-d425-5cbc-854d-e995e4a1c5fa', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice most logically completes the text?', '["the number of buildings at Çatalhöyük would have been sufficient to accommodate a population that expanded from 8,000 to 10,000 inhabitants by 5950 BCE.", "the use of mud bricks is a reliable indicator that a structure had been used either as a dwelling or for nonresidential purposes.", "the density of excavated buildings at Çatalhöyük can serve as a proxy for how many people inhabited the village at a given time.", "the buildings excavated at Çatalhöyük at the time of Mellaart’s research had served a residential purpose as early as 7100 BCE."]'::jsonb, 14, 'In 1967, archaeologist James Mellaart claimed that at its peak, Çatalhöyük—a 33-acre Neolithic village in present-day Turkey that dates from approximately 7100 to 5950 BCE—housed between 8,000 to 10,000 residents, an estimate based on the excavation of dense clusters of mud brick buildings that were thought to have been dwellings. Arguing that such estimates should be reevaluated, Ian Kuijt and Arkadiusz Marciniak (2024) cite radiocarbon data and ethnographic modeling that suggest the heterogeneity of building use in Çatalhöyük, with many individual buildings being inhabited for relatively brief periods—20 to 30 years or less—before being abandoned or repurposed for nonresidential functions (e.g., storage). Accordingly, these recent findings challenge the assumption that ______.'),
  ('7f05f891-5271-57ba-9ca5-116af4886dc0', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice most logically completes the text?', '["the nitrogen storage environment in which the Bennu material was transported may have facilitated the formation of sodium-rich evaporites that then deteriorated when exposed to atmospheric humidity typical of most nondesert locations on Earth.", "the sodium evaporite concentrations on Bennu may have once been similar to those on recovered chondrites, but exposure to Earth’s atmospheric humidity affected Bennu’s evaporites and led to new compound formation.", "sodium-rich evaporites are scarce on recovered chondrites in part due to the length of time those chondrites have been exposed to much lower humidity levels than those typically found on Earth.", "the discrepancy between sodium evaporite concentrations on recovered chondrites and those initially observed on the Bennu material may be attributable to the chondrites’ exposure to atmospheric humidity typical of many Earth environments."]'::jsonb, 15, 'Chondrite meteorites recovered on Earth tend to show negligible concentrations of sodium-rich evaporites. Following collection in space and return to Earth in controlled nitrogen environments with extremely low (1%) humidity, material from the asteroid Bennu—which shares compositional features with a chondrite subclass—was found to have significant sodium evaporite concentrations. After five months in Earth air at 30%–40% humidity (lower-than-average humidity for most nondesert Earth locations), a small sample of Bennu material showed significant evaporite deterioration and new compound formation; after eight months in similar conditions, another sample experienced complete loss of sodium evaporites. Together, these observations suggest that ______.'),
  ('283508ca-5228-5a3c-8af5-75878810270d', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice most logically completes the text?', '["less-affluent citizens were reluctant to risk incurring a fine and thus voluntarily complied with the laws even in the absence of regular enforcement.", "the few fines that were imposed under the laws were tolerable to wealthy offenders and thus did not help the laws serve their intended purpose.", "authorities focused enforcement on the wealthiest offenders, recognizing that pursuing offenders who were unable to pay the fines could weaken fines’ effectiveness as a deterrent.", "the public announcement of fines could signal offenders’ wealth and status, placing enforcement of the laws in conflict with their intent."]'::jsonb, 16, 'The Lex Iulia sumptuaria of 18 BCE was one in a succession of ancient Roman sumptuary laws governing expenditures on luxury, primarily regulating large banquets and other lavish events. Such laws, enacted against a backdrop of anxiety about social dynamism, were intended to limit aspirational overreaching for status but were infrequently enforced. Moreover, enforcement was generally limited to fines, which, when levied against high-profile offenders, were widely announced. The affluent accepted fines as merely a tax on privilege, even as the amounts increased with frequent revisions to the laws. Historians have therefore argued that enforcing sumptuary laws only minimally may have been a way to avoid undermining the laws’ aims, given that ______.'),
  ('38b76830-4e31-5b7d-b987-ad18a4ac8fc9', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["to realize", "are realizing", "is to realize", "realizing"]'::jsonb, 17, 'To experience both the multi-instrument groove of contemporary blues music and the stripped-down Delta blues of Andy Rodgers and other blues forebearers ______ the rich history of the genre.'),
  ('6410fcdd-16d0-5679-b4f4-0f5c2f38ed5e', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["they’re", "their", "its", "it’s"]'::jsonb, 18, 'In 1840, Rowland Hill’s penny postage system revolutionized mail in Britain, rendering obsolete previous systems in which senders paid variable rates based on distance traveled and recipients often refused delivery to avoid owing postage. Following ______ lead came similar systems implemented by reformers in other nations, such as Wilhelm Naeff in Switzerland and José Clemente Pereira in Brazil.'),
  ('e4c6c54f-04e4-5a04-b2dd-63524e24c1c4', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["goal. Catching", "goal: catching", "goal; catching", "goal catching"]'::jsonb, 19, 'An accomplished birder might be able to spot thousands of different species over the course of a career, from Camaroptera brachyura to Buteo brachyurus, but no birder has ever achieved the ultimate ______ an in-person glimpse of all 10,000-plus species of birds.'),
  ('28f4b943-e57a-5a70-b3a9-c3988c575168', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["paleogeneticist Emrah Kurdök", "paleogeneticist, Emrah Kurdök", "paleogeneticist, Emrah Kurdök,", "paleogeneticist Emrah Kurdök,"]'::jsonb, 20, 'The Huseby Klev archaeological site in Sweden was exceptionally well-preserved beneath a layer of clay, which sealed artifacts into what scientists describe as a natural geological time capsule. As a result, ______ and his colleagues were able to extract and analyze DNA from chewed tree resin dating back nearly 10,000 years.'),
  ('da7e6382-74ef-50ed-97e5-009215c24807', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["paintings;", "paintings", "paintings.", "paintings,"]'::jsonb, 21, 'When historian John Irwin founded the Museum of Appalachia in Clinton, Tennessee, in the 1960s, it consisted of just a single log structure. Today, it is a 65-acre living history museum featuring vast collections of folk art, including carvings, textiles, and ______ Arnwine Cabin, one of thirty-five historic log buildings on the property; and a re-created pioneer-era Appalachian farm.'),
  ('650d7839-cddf-5b17-acf1-7f9c675d2945', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["plates, each was", "plates; each being", "plates, each", "plates; each"]'::jsonb, 22, 'Mary Elizabeth Banning was a self-taught mycologist, or fungi specialist, who researched mushrooms in the late 1800s. Banning documented her findings in The Fungi of Maryland, an unpublished manuscript consisting of 175 watercolor ______ a detailed portrait of a particular species, such as Polyporus beattei, a fungi species of the order Hymenomycetes presented on plate 118.'),
  ('46c505c7-0a92-5dcb-8a26-b3f0767e1c2d', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text with the most logical transition?', '["as a result,", "for instance,", "in addition,", "however,"]'::jsonb, 23, 'In biology there is no single agreed-upon concept of what defines a species; ______ numerous competing species concepts are used within the field, a dilemma known as the species problem. The genotypic cluster species concept, described in 1995 by Mallet, defines species in accordance with genetic similarity, while the general lineage species concept, delineated by Queiroz in 1998, organizes species according to evolutionary lineage.'),
  ('20d9cd47-d88b-5dde-8139-36f840961978', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice completes the text with the most logical transition?', '["Likewise,", "Nevertheless,", "Thus,", "Indeed,"]'::jsonb, 24, 'Massimo Coli and colleagues used ground-penetrating radar (GPR) to map moisture infiltration within the walls of Saint John Baptistery in Florence, Italy. The contrast between wet and dry materials produces vivid radar echoes that delineate leak pathways, yet the presence of water-saturated zones also hampers the efficacy of the technique. ______ even as GPR makes such areas conspicuous, water within masonry absorbs and scatters radar energy, often obscuring defects in layers beyond the saturated region.'),
  ('89b1cf55-d811-5b73-9400-d0ee8663e8b2', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'Which choice most effectively uses information from the given sentences to emphasize the different years in which the books reached the NYT Best Sellers list?', '["Ta-Nehisi Coates and Tayari Jones are both NYT best-selling authors.", "Ta-Nehisi Coates’s Between the World and Me and Tayari Jones’s An American Marriage are both NYT best sellers, but the former is a nonfiction book, whereas the latter is a novel.", "The nonfiction book Between the World and Me became an NYT best seller in 2015; An American Marriage, a novel, joined this list as well, but in 2018.", "Between the World and Me and An American Marriage are both books by Black authors that have reached the NYT Best Sellers list."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:
Since 1931, the New York Times (NYT) Best Sellers list has been a measure of the most successful books in the US.
Ta-Nehisi Coates and Tayari Jones are Black authors who have reached the NYT Best Sellers list. Between the World and Me is a nonfiction book by Ta-Nehisi Coates. It reached the NYT Best Sellers list on August 2, 2015.
An American Marriage is a novel by Tayari Jones. It reached the NYT Best Sellers list on February 6, 2018.'),
  ('6bc1272e-5b7d-5159-aadc-0e2196d379b6', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'The student wants to explain how the kingfisher’s beak structure was used to solve the bullet train’s sonic boom problem. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Nakatsu discovered that the kingfisher’s beak structure eliminated sonic booms, and the redesign improved the train’s transition between tunnel and open-air environments.", "Nakatsu’s observation of kingfishers diving into water showed how the bird’s beak structure could help the train eliminate sonic booms.", "By redesigning the train’s nose to imitate the kingfisher’s gradually widening beak shape, engineers improved the train’s transition between tunnels and open air, eliminating sonic booms.", "The shape of the kingfisher’s beak inspired engineers to reshape the train nose into one that gradually widens, allowing the train to move smoothly between air and water."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

The Shinkansen (bullet train) is a network of high-speed railways in Japan.
1960s: The trains’ high speeds created intense pressure waves that produced sonic booms when trains exited tunnels.
1980s: Engineer Eiji Nakatsu noted that the kingfisher bird could dive into water at high speeds while barely creating a splash.
The kingfisher’s beak gradually widens from tip to head, allowing smooth transition between air and water.
Nakatsu and other engineers redesigned the train nose based on the kingfisher’s beak structure to improve the transition between tunnel and open-air environments.
The redesign reduced pressure buildup, eliminating sonic booms.'),
  ('5474930d-f19d-5ce7-a689-cf0a6472dbcc', 'ee659f38-5a01-5444-960a-72a03ecf92e7', 'The student wants to emphasize a similarity between Robert Frost and Sinclair Lewis. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Both New Hampshire and Arrowsmith are in the public domain; however, one is a poetry collection and the other a novel.", "The year was 2021, and the copyright to Sinclair Lewis’s Arrowsmith had finally expired.", "New Hampshire, a poetry collection by Robert Frost, entered the public domain in 2019, unlike Sinclair Lewis’s novel Arrowsmith.", "Robert Frost and Sinclair Lewis are two authors whose works recently entered the public domain."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

A copyright prevents a book’s contents from being reproduced (published) without permission from the copyright holder.
When a book’s copyright expires, the book enters the public domain and can be legally reproduced by anyone.
New Hampshire is a poetry collection by Robert Frost. It entered the public domain in 2019. Arrowsmith is a novel by Sinclair Lewis. It entered the public domain in 2021.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('43240bcc-7c2a-5df7-96a7-faaf573219c4', 3, null, 'Specialists are needed to interpret the flagged activity, so much of it is unclear: "ambiguous."'),
  ('8266c14f-5ac9-59aa-a8a8-c2bf2c1d6167', 1, null, 'Gases, moisture and debris must be purged from the lines: technicians are "evacuating" them.'),
  ('fe610683-8f5f-5106-bef1-6266aa4bd6be', 2, null, 'Most of the cost comes from the truck being on the road, so firms are unwilling ("loath") to send trucks that aren''t full.'),
  ('ae4492d4-19e1-599c-847c-901a4ba67526', 3, null, 'If plants prefer nickel, the soil would seem easy to clean with plants: "amenable to" decontamination.'),
  ('d0c9db1b-2a5a-5e4a-904f-a493983f3d5e', 0, null, 'If plants prefer nickel, the soil would seem easy to clean with plants: "amenable to" decontamination.'),
  ('6da77714-8783-5338-8502-c7da9829bad6', 1, null, '"It often heats food unevenly" names a weakness of microwave heating.'),
  ('131e6aa5-7af8-54ff-a0a0-7d7cbc9bf5ef', 1, null, 'The text defines positive expressive writing and its techniques, then reports Hoult''s finding.'),
  ('fd761735-fdc6-515f-9ead-9a5a353bfe47', 1, null, 'Both use shared identity to spur action: Text 1 all of humanity, Text 2 a narrower group (young people).'),
  ('fb2e03a0-bfc6-5beb-88f2-5ef721bbc2e8', 1, null, 'Color (white butterflies on green flowers) and weather (feeding on cloudy days) were both linked to behavior.'),
  ('8d15134e-6b62-5234-8b48-719bfb0bb66d', 3, null, 'The ratios fall from core to rim to matrix (0.71685 to 0.71416) but stay above 0.710: crustal influence decreases but persists.'),
  ('0a56af3a-5e91-5383-a32b-10317d7a62dc', 3, null, 'From 7:00 to 8:00 p.m., outside rush hours, delays rose on both road types (1.98 and 1.32).'),
  ('72e3f2ef-053c-52de-9a9a-b2d22bb7e20d', 0, null, 'If the split already existed about 2,000 years ago, a fence built 150 years ago cannot be its cause.'),
  ('4816b15a-d7a9-5fb9-abb2-0a63bc3c7e0d', 2, null, 'High-pressure cements would have lower Ge/Si than the grains; a mismatch with that pattern supports rapid ocean-silica preservation.'),
  ('d40da08f-d425-5cbc-854d-e995e4a1c5fa', 2, null, 'Many buildings were used briefly or not as homes, so counting buildings does not give a population.'),
  ('7f05f891-5271-57ba-9ca5-116af4886dc0', 3, null, 'Bennu''s evaporites vanished after months in humid air, so chondrites may lack them because of Earth humidity.'),
  ('283508ca-5228-5a3c-8af5-75878810270d', 3, null, 'Widely announced fines could advertise an offender''s wealth, which works against laws meant to limit status display.'),
  ('38b76830-4e31-5b7d-b987-ad18a4ac8fc9', 2, null, 'The infinitive subject "To experience..." needs a singular finite verb: "is to realize."'),
  ('6410fcdd-16d0-5679-b4f4-0f5c2f38ed5e', 2, null, 'The antecedent is the singular system (Hill''s penny postage system): "its."'),
  ('e4c6c54f-04e4-5a04-b2dd-63524e24c1c4', 1, null, 'A colon introduces the explanation of the "ultimate goal."'),
  ('28f4b943-e57a-5a70-b3a9-c3988c575168', 0, null, '"Paleogeneticist Emrah Kurdök" is a restrictive title plus name: no commas.'),
  ('da7e6382-74ef-50ed-97e5-009215c24807', 0, null, 'List items contain commas, so they are separated with semicolons.'),
  ('650d7839-cddf-5b17-acf1-7f9c675d2945', 2, null, '"each a detailed portrait..." is an absolute phrase joined to the sentence with a comma.'),
  ('46c505c7-0a92-5dcb-8a26-b3f0767e1c2d', 0, null, 'Because there is no agreed concept, many competing concepts are used: "as a result."'),
  ('20d9cd47-d88b-5dde-8139-36f840961978', 3, null, 'The sentence elaborates on how saturated zones hamper GPR: "Indeed."'),
  ('89b1cf55-d811-5b73-9400-d0ee8663e8b2', 2, null, 'Only this choice gives both years (2015 and 2018).'),
  ('6bc1272e-5b7d-5159-aadc-0e2196d379b6', 2, null, 'It links the beak''s widening shape to the nose redesign and the end of sonic booms.'),
  ('5474930d-f19d-5ce7-a689-cf0a6472dbcc', 3, null, 'It states what the two authors share: their works recently entered the public domain.')
