insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('8dec6221-3f1d-5c80-a014-c0fb92d7298b', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'Sphere A and Sphere B are tangent to each other at point $P$. Segment $MP$ is a diameter of Sphere A, segment $NP$ is a diameter of Sphere B, and point $P$ lies on line segment $MN$. The radius of Sphere A is $5$ times the radius of Sphere B. If the volume of Sphere B is $288π$ cubic inches, what is the length of segment $MN$, in inches?', '[]'::jsonb, 1, null),
  ('7bb726f5-2a48-5d83-9557-77e182b37a75', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'To cut a lawn, Antwan charges a fee of \$10.00 for his equipment and \$8.50 per hour spent cutting a lawn. Taylor charges a fee of \$7.00 for his equipment and \$9.50 per hour spent cutting a lawn. If $x$ represents the number of hours spent cutting a lawn, what are the values of $x$ for which Taylor’s total charge is greater than Antwan’s total charge?', '["$2 \\le x \\le 3$", "$3 \\le x \\le 4$", "$x < 2$", "$x > 3$"]'::jsonb, 2, null),
  ('a3685175-ff48-5943-92a1-a5ae6c889ba0', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'The relationship between the variables $x$ and $y$ is defined by an exponential equation. When $x = 0$ the value of $y$ is $30$, and for every increase in the value of $x$ by $1$, the corresponding value of $y$ increases by 70% of its previous value. Which equation represents this relationship?', '["$y = 30(1.70)^{x}$", "$y = 30(1.07)^{x}$", "$y = 70(1.30)^{x}$", "$y = 70(1.03)^{x}$"]'::jsonb, 3, null),
  ('06d1026e-f544-5fa7-b963-92edc65d7d9b', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'In the figure shown, lines $a$, $b$, and $c$ are parallel. If $201 < x + y + z < 212$, which of the following could be true?
I. $w - y = 22$
II. $w - y = 32$', '["I only", "II only", "I and II", "Neither I nor II"]'::jsonb, 4, '![figure](/q/aug26/001.webp)'),
  ('27338104-41cd-56af-aa7a-fb339d71fa4f', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'A circle has center $O$, and points $P$ and $Q$ lie on the circle such that segment $PQ$ is a diameter of the circle. The length of arc $PQ$ is $56$ centimeters. What is the circumference, in centimeters, of the circle?', '["$42$", "$56$", "$112$", "$224$"]'::jsonb, 5, null),
  ('b4d519a0-4c01-5b54-9d7a-0f1cf0e3d9ea', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'In 2004, Aster earned 11% more than in 2003, and in 2005 Aster earned 6% more than in 2004. If Aster earned $y$ times as much in 2003 as in 2005, which of the following is closest to the value of $y$?', '["$0.5455$", "$0.6600$", "$0.8409$", "$1.1766$"]'::jsonb, 6, null),
  ('5afc792e-72e6-593d-8048-c7a7aeaea7b1', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'A community organization surveyed a random sample of residents to estimate the percentage of residents who visit their local library at least once per month. The organization estimates that 19% of residents visit the library at least once per month, with an associated margin of error of 3.7%. The organization repeated the survey with a random sample that was double the original sample size. Which of the following is true about the margin of error associated with the estimate from the larger sample?', '["The margin of error is less than 3.7%.", "The margin of error is 7.4%.", "The margin of error is greater than 19%.", "The margin of error is 38%."]'::jsonb, 7, null),
  ('a77981d6-086d-5213-8826-71e6168f65ea', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'Two data sets of $23$ integers each are summarized in the histograms shown. For each of the histograms, the first interval represents the frequency of integers greater than or equal to $10$, but less than $20$. The second interval represents the frequency of integers greater than or equal to $20$, but less than $30$, and so on. What is the smallest possible difference between the mean of data set A and the mean of data set B?', '["$0$", "$1$", "$10$", "$23$"]'::jsonb, 8, '![figure](/q/aug26/002.webp)'),
  ('b39b5fd6-ec4e-5609-8702-8ab25a633ba8', '54ed5493-3d57-5d07-9488-c65e99bd340b', '$g(x) = (x + 14)(t - x)$
The function $g$ is defined by the given equation, where $t$ is a constant. In the $xy$-plane, the graph of $y = g(x)$ passes through the point $(18,0)$. What is the value of $g(0)$?', '[]'::jsonb, 9, null),
  ('c203025f-295b-5622-a4cb-cea9931f19e4', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'In the ancient Roman measurement system, a leuga was a unit of length that was equal to $7,500$ pedes. In this measurement system, how many pedes were equivalent to $4.2$ leugas?', '[]'::jsonb, 10, null),
  ('8aaaff09-fb81-57b2-a6be-9f1ea43622ac', '54ed5493-3d57-5d07-9488-c65e99bd340b', '$y = \frac{35 - x}{ax + b}$
What is the $x$-intercept of the graph of the equation in the $xy$-plane, where $a$ and $b$ are positive constants?', '["$(35,0)$", "$(0,-35)$", "$(0, \\frac{35}{b})$", "$(-\\frac{b}{a},0)$"]'::jsonb, 11, null),
  ('5b0bb2b0-bb10-506f-bb6d-937a78220349', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'A triathlon is a multisport race consisting of three different consecutive events. A triathlon participant plans to complete the cycling event with an average speed of $31,680$ yards per hour. What is this average speed, in miles per hour? ($1$ mile $= 1,760$ yards)', '[]'::jsonb, 12, null),
  ('a4d7e02b-fdb1-51dc-8bb0-ffb89d11dd30', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'The figure shown is a right rectangular pyramid, where $l = 16$ units, $w = 8$ units, and $h = 18$ units. What is the surface area, in square units, of the pyramid?', '[]'::jsonb, 13, '![figure](/q/aug26/003.webp)'),
  ('ec40cbe0-959e-5926-9519-49704d2a3b03', '54ed5493-3d57-5d07-9488-c65e99bd340b', '$f(x) = 18(2.80)^{\frac{x}{2}}$
The function $f$ is defined by the given equation. The value of $f(x)$ increases by $p%$ for every increase of $x$ by $4$. For which of the following functions, where $n$ is a positive constant, does the value of $g(x)$ increase by $p%$ for every increase of $x$ by $1$?', '["$g(x) = n(1.40)^{x}$", "$g(x) = n(2.80)^{x}$", "$g(x) = n(6.84)^{x}$", "$g(x) = n(7.84)^{x}$"]'::jsonb, 14, null),
  ('2803186b-c507-55da-a491-ff78f553e8dc', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'The scatterplot shows $9$ data points and their line of best fit. For how many of the $9$ data points is the actual $y$-value greater than the $y$-value predicted by the line of best fit?', '["$8$", "$7$", "$5$", "$2$"]'::jsonb, 15, '![figure](/q/aug26/004.webp)'),
  ('5bc686f8-e3be-553e-9365-22dc32e7f930', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'In triangles $RST$ and $XY Z$ shown, $\overline{XY}$ is parallel to $\overline{TS}$ and $\tan R = \frac{160}{231}$. What is the value of $\sin X$ in triangle $XY Z$?', '["$\\frac{160}{391}$", "$\\frac{160}{281}$", "$\\frac{231}{281}$", "$\\frac{231}{160}$"]'::jsonb, 16, '![figure](/q/aug26/005.webp)'),
  ('054add70-d645-579d-9dc6-00736b5a2881', '54ed5493-3d57-5d07-9488-c65e99bd340b', '$f(x) = (x - 3)(x + 5)$
The function $f$ is defined by the given equation. The function $g$ is defined by $g(x) = f(x - 2) + 4$. Which of the following equations is an equivalent form of $g(x)$ that displays the minimum value of $g$ as a constant or coefficient?', '["$g(x) = (x - 5)(x + 3) + 4$", "$g(x) = (x + 1)^{2} - 12$", "$g(x) = (x - 1)^{2} - 12$", "$g(x) = x^{2} - 2x - 11$"]'::jsonb, 17, null),
  ('cbb50798-46c3-5393-8518-7db178516770', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'A researcher investigated two species of mites: a predator and its prey. At the start of a week, there was an equal number of the two species. At the end of the week, the number of prey had increased by 1,900% of the number of prey at the start of the week, and the number of predators had increased by 220% of the number of predators at the start of the week. The number of predators at the end of the week was $p%$ less than the number of prey at the end of the week. What is the value of $p$?', '[]'::jsonb, 18, null),
  ('c0b28551-26a2-581c-93fa-61b224da8239', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'Each $3.0$-ounce serving of cheddar cheese and each $1.2$-ounce serving of tuna provides about $1$ microgram of vitamin B12. If a total of $3.5$ micrograms of vitamin B12 are consumed from eating $x$ ounces of cheese and $y$ ounces of tuna, which equation best represents this situation?', '["$0.33x + 0.33y = 3.5$", "$3.0x + 1.2y = 3.5$", "$1.2x + 3.0y = 3.5$", "$0.33x + 0.83y = 3.5$"]'::jsonb, 19, null),
  ('66519c83-b339-5ae0-b1f0-c3282a7e1743', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'In triangle $RST$, $RS = 504$, $ST = 128$, and $TR = 520$. Triangle $RST$ is similar to triangle $UV W$, where $S$ corresponds to $V$ and $T$ corresponds to $W$. What is the value of $\tan W$?', '["$\\frac{16}{65}$", "$\\frac{16}{63}$", "$\\frac{63}{65}$", "$\\frac{63}{16}$"]'::jsonb, 20, null),
  ('682144e0-1368-59b9-a96c-71dd94642b27', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'Which of the following data sets has the largest standard deviation, where $p$ is a constant?', '["$p - 10$, $p - 5$, $p$, $p - 2$, $p + 2$", "$p - 5$, $p - 5$, $p$, $p$, $p - 2$", "$p - 2$, $p + 2$, $p$, $p$, $p - 5$", "$p$, $p$, $p$, $p$, $p$"]'::jsonb, 21, null),
  ('90a1e763-5c2a-5cc8-8d5d-d4f07b10d78d', '54ed5493-3d57-5d07-9488-c65e99bd340b', 'In the equation $7x(x + 11) = r$, $r$ is a positive integer. How many distinct real solutions does the equation have for $x$?', '["Zero", "Exactly one", "Exactly two", "Infinitely many"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('8dec6221-3f1d-5c80-a014-c0fb92d7298b', null, array['72']::text[], '$\frac{4}{3}πr^{3} = 288π$ gives $r = 6$ for Sphere B, so Sphere A has radius $30$. $MN = 2(30) + 2(6) = 72$.'),
  ('7bb726f5-2a48-5d83-9557-77e182b37a75', 3, null, 'Taylor costs more when $7 + 9.5x > 10 + 8.5x$, that is, $x > 3$.'),
  ('a3685175-ff48-5943-92a1-a5ae6c889ba0', 0, null, 'Starting value $30$, growth of 70% per step: $y = 30(1.70)^{x}$.'),
  ('06d1026e-f544-5fa7-b963-92edc65d7d9b', 0, null, 'Alternate interior angles give $w = x + y$; co-interior angles give $y + z = 180$. So $x + y + z = x + 180$, which means $21 < x < 32$, and $w - y = x$. $22$ is possible, $32$ is not.'),
  ('27338104-41cd-56af-aa7a-fb339d71fa4f', 2, null, 'A diameter cuts the circle into two equal arcs, so the circumference is $2(56) = 112$.'),
  ('b4d519a0-4c01-5b54-9d7a-0f1cf0e3d9ea', 2, null, '2005 earnings $= (1.11)(1.06) = 1.1766$ times 2003 earnings, so $y = 1/1.1766 ≈ 0.85$, closest to $0.8409$.'),
  ('5afc792e-72e6-593d-8048-c7a7aeaea7b1', 0, null, 'A larger random sample gives a smaller margin of error.'),
  ('a77981d6-086d-5213-8826-71e6168f65ea', 0, null, 'The histograms are identical, so the two data sets can be identical, giving a difference of $0$.'),
  ('b39b5fd6-ec4e-5609-8702-8ab25a633ba8', null, array['252']::text[], '$g(18) = 32(t - 18) = 0$ gives $t = 18$, so $g(0) = (14)(18) = 252$.'),
  ('c203025f-295b-5622-a4cb-cea9931f19e4', null, array['31500']::text[], '$4.2 \times 7,500 = 31,500$ pedes.'),
  ('8aaaff09-fb81-57b2-a6be-9f1ea43622ac', 0, null, '$y = 0$ when $35 - x = 0$, so $x = 35$ (the denominator $35a + b$ is not zero).'),
  ('5b0bb2b0-bb10-506f-bb6d-937a78220349', null, array['18']::text[], '$31,680 \div 1,760 = 18$ miles per hour.'),
  ('a4d7e02b-fdb1-51dc-8bb0-ffb89d11dd30', null, array['580.6', '580.61', '580.607']::text[], 'Base $16 \cdot 8 = 128$. Slant heights: $\sqrt{18^{2} + 4^{2}} = \sqrt{340}$ (faces on the 16 side) and $\sqrt{18^{2} + 8^{2}} = \sqrt{388}$ (faces on the 8 side). Total $128 + 16\sqrt{340} + 8\sqrt{388} ≈ 580.6$.'),
  ('ec40cbe0-959e-5926-9519-49704d2a3b03', 3, null, 'When $x$ grows by $4$, $f$ is multiplied by $2.80^{2} = 7.84$. A function that grows by the same percent per unit of $x$ is $n(7.84)^{x}$.'),
  ('2803186b-c507-55da-a491-ff78f553e8dc', 2, null, 'Five points lie above the line of best fit: near $x ≈ 3.6, 5.9, 6.5, 8.4$ and $9.7$.'),
  ('5bc686f8-e3be-553e-9365-22dc32e7f930', 2, null, 'In right triangle $RTS$, $\tan R = \frac{160}{231}$, so $RS = 281$. Because $\overline{XY} \parallel \overline{TS}$, angle $X$ equals angle $S$, and $\sin S = \frac{231}{281}$.'),
  ('054add70-d645-579d-9dc6-00736b5a2881', 2, null, '$g(x) = (x - 5)(x + 3) + 4 = x^{2} - 2x - 11 = (x - 1)^{2} - 12$, which shows the minimum $-12$.'),
  ('cbb50798-46c3-5393-8518-7db178516770', null, array['84']::text[], 'With $N$ of each at the start: prey $20N$ and predators $3.2N$ at the end. $\frac{20 - 3.2}{20} = 0.84$, so $p = 84$.'),
  ('c0b28551-26a2-581c-93fa-61b224da8239', 3, null, 'Cheese gives $\frac{x}{3.0} ≈ 0.33x$ micrograms and tuna $\frac{y}{1.2} ≈ 0.83y$, so $0.33x + 0.83y = 3.5$.'),
  ('66519c83-b339-5ae0-b1f0-c3282a7e1743', 3, null, '$504^{2} + 128^{2} = 520^{2}$, so angle $S$ is right. $\tan T = \frac{504}{128} = \frac{63}{16}$, and $W$ corresponds to $T$.'),
  ('682144e0-1368-59b9-a96c-71dd94642b27', 0, null, 'Its values spread from $p - 10$ to $p + 2$, farther from the mean than any other set.'),
  ('90a1e763-5c2a-5cc8-8d5d-d4f07b10d78d', 2, null, '$7x^{2} + 77x - r = 0$ has discriminant $77^{2} + 28r > 0$, so it has exactly two real solutions.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

