values ('d9754c4b-831b-53af-95cb-e6579ccdd3e2', 'PeaklyTest Aug 2026 · Math · Module 2', 'Math', 'Math, Module 2 of the Aug 2026 PeaklyTest · 22 questions · 35 minutes', 35, 123, true, 'PeaklyTest Aug 2026 · Math', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
