insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('e031435d-0d32-51c0-b4d8-359c63a73cb4', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'A rectangle is inscribed in a circle. If the length of the diagonal of the rectangle is $482\sqrt{3}$, what is the radius of the circle?', '["$241\\sqrt{3}$", "$482\\sqrt{3}$", "$964\\sqrt{3}$", "$241\\sqrt{6}$"]'::jsonb, 1, null),
  ('c74e8f33-98c5-5bc2-a085-c4365715314f', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'What is the sum of the solutions to the equation $x^{2} - 90x - 18 = 0$?', '["$-90$", "$-18$", "$18$", "$90$"]'::jsonb, 2, null),
  ('f9f28697-c6a8-571d-a602-d6df59c6ad17', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'In the $xy$-plane, the function $g(x)$ is defined as $g(x) = \frac{f(x)}{x+4}$. If the $y$-intercept of the graph of $y = g(x)$ is $(0,54)$, what is the value of $f(0)$?', '["$13.5$", "$54$", "$216$", "$220$"]'::jsonb, 3, null),
  ('1944b6c7-5b45-5095-937a-fd6487fb0431', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'A square pyramid has a base side length of $a = 4$ units and a height of $h = 6$ units. What is the volume of the pyramid in cubic units?', '["$8$", "$16$", "$32$", "$48$"]'::jsonb, 4, null),
  ('fc8abd56-bf98-55aa-9a28-63ceb901e01a', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'The graph of a quadratic function $y = f(x)$ opens upward with its vertex located below the line $y =$ $-9$. Which of the following could be the number of real solutions to the equation $f(x) = -9$?', '["Zero", "Exactly one", "Exactly two", "Infinitely many"]'::jsonb, 5, null),
  ('701d658f-d08c-5a56-9389-b8204a604807', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'If $7(x - 4)^{2} = 700$ and $x > 0$, what is the value of $x$?', '["$6$", "$10$", "$14$", "$104$"]'::jsonb, 6, null),
  ('174e0989-26e1-5743-b095-6cef1a136cf0', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'Line $j$ passes through the points $(12,0)$ and $(8,0)$ in the $xy$-plane. Line $k$ is perpendicular to line $j$ and passes through the origin $(0,0)$. At what $x$-coordinate do line $j$ and line $k$ intersect?', '["$-12$", "$0$", "$8$", "$10$"]'::jsonb, 7, null),
  ('9da719bf-0007-508f-b24d-31a9ea87c39d', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'A quadratic function $f(x)$ satisfies $f(0) = 3$ and $f(8) = 3$. Which of the following equations could define $f(x)$?', '["$f(x) = x(x - 8) + 3$", "$f(x) = x(x + 8) + 3$", "$f(x) = (x - 3)(x - 8)$", "$f(x) = 3x^{2} - 8x$"]'::jsonb, 8, null),
  ('7eac25d0-ca9e-587a-90d9-d39500b05a65', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'In triangle $ABC$, angle $C$ is a right angle ($\angle C = 90°$). Point $E$ lies on side $\overline{AC}$ such that $CE = 2 \cdot AE$, and point $D$ lies on side $\overline{AB}$ such that segment $\overline{ED}$ is perpendicular to $\overline{AC}$. If $BC = 198$, what is the length of segment $\overline{ED}$?', '["$66$", "$99$", "$132$", "$396$"]'::jsonb, 9, null),
  ('40613a85-970f-57c3-b863-fe7b400d8f48', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', '$f(x) = 16 - \frac{x}{27}$
The function $f$ is defined by the given equation. What is the value of $f(270)$?', '["$-10$", "$6$", "$10$", "$26$"]'::jsonb, 10, null),
  ('12078bec-569c-5682-87d0-e309725004cb', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', '$y = 6$
$y = -4x + 2$
A system of linear equations is given. What is the solution $(x,y)$ to the system?', '["$(-1,6)$", "$(1,6)$", "$(6,-1)$", "$(6,22)$"]'::jsonb, 11, null),
  ('7e016b56-3012-5ad8-a221-b5b523c7ddc4', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'The total remaining distance, in miles, of a runner after $t$ hours is modeled by the function $g(t) =$ $22 - 4t$. What is the best interpretation of the number $22$ in this context?', '["The speed of the runner in miles per hour", "The total time taken to finish the run", "The initial total distance, in miles, of the run", "The distance covered in the first hour"]'::jsonb, 12, null),
  ('6740f591-5655-5bf0-9c12-fbdebb80e197', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'A quantity decreases by 20% every $5$ seconds. If the initial value of the quantity is $340$, which function $f(x)$ represents the value of the quantity after $x$ seconds?', '["$f(x) = 340(0.2)^{5x}$", "$f(x) = 340(0.8)^{5x}$", "$f(x) = 340(0.2)^{\\frac{x}{5}}$", "$f(x) = 340(0.8)^{\\frac{x}{5}}$"]'::jsonb, 13, null),
  ('5a19c1ac-11af-5037-ac93-c73eb79d0ab9', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'A company’s annual revenue was $x$ dollars in 2012. The revenue increased by 12% from 2012 to 2013, and increased by 4% from 2013 to 2014. If the revenue in 2014 was $y$ times the revenue in 2012, which expression represents $y$?', '["$(1.12)(1.04)$", "$(1.12) + (1.04)$", "$\\frac{1.04}{1.12}$", "$\\frac{1}{(1.12)(1.04)}$"]'::jsonb, 14, null),
  ('5c2a6441-232f-5ebd-a45d-37a54c8fd6f4', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', '', '["Linear", "Exponential decay", "Quadratic", "Absolute value"]'::jsonb, 15, 'The table shows values of $x$ and $y$. Which type of function best models the relationship between $x$ and $y$?

| $x$ | $1$ | $2$ | $3$ | $4$ |
| $y$ | $4,000$ | $2,400$ | $1,440$ | $864$ |'),
  ('c916faa5-2398-5d3f-89f5-cbee71f47f0a', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'During a triathlon, an athlete swims at a rate of $31,152$ inches per hour. Given that $1$ yard $= 36$ inches, what is this speed in yards per hour?', '["$17.7$", "$865.33$", "$1,760$", "$8,653.33$"]'::jsonb, 16, null),
  ('468765f6-7954-59eb-93ff-e05fac82da20', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'The scatterplot shows the relationship between two variables, $x$ and $y$. A line of best fit is also shown. For $x = 5$, how much greater is the $y$-value predicted by the line of best fit than the actual $y$- value of the data point?', '["$1$", "$5$", "$6$", "$11$"]'::jsonb, 17, '![figure](/q/aug26/006.webp)'),
  ('a61c327c-de18-56cf-b5ff-eed0f420878c', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', '$g(x) = -\sqrt{x^{2} + bx + c}$
The function $g$ is defined by the given equation, where $b$ and $c$ are integers. In the $xy$-plane, the graph of $y = g(x)$ passes through the points $(2,0)$ and $(0,-\sqrt{298})$. If $m$ is a value for which $g(m) = 0$, what is the greatest possible value of $m$?', '["$-150$", "$2$", "$149$", "$150$"]'::jsonb, 18, null),
  ('144a2855-d23b-5d59-a6c2-fbaa877ea12d', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', '$18p - 19p = 17$
What is the value of $p$ that satisfies the equation?', '["$-17$", "$-\\frac{1}{17}$", "$17$", "$37$"]'::jsonb, 19, null),
  ('be2c37c4-c960-53d7-9317-5bdbe05d3caf', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'Points $A$ and $B$ lie on a circle centered at point $C$. If the length of line segment $\overline{AC}$ is $34$ mm, what is the length of segment $\overline{BC}$?', '["$17$ mm", "$34$ mm", "$68$ mm", "$115.6$ mm"]'::jsonb, 20, null),
  ('0575fb67-9b8e-53ad-aeaa-3678ad1b3889', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', 'Which of the following expressions is equivalent to $\frac{4}{x-5} - \frac{4}{(x-5)^{2}}$ for all $x > 5$?', '["$\\frac{0}{(x-5)^{2}}$", "$\\frac{4x-24}{(x-5)^{2}}$", "$\\frac{4x-16}{(x-5)^{2}}$", "$\\frac{4}{x-5}$"]'::jsonb, 21, null),
  ('f8c135ce-5b10-5b74-9dda-e0f2f53ec6ad', 'd9754c4b-831b-53af-95cb-e6579ccdd3e2', '$3x = 2 + 8y$
$-3x = -5 + 8y$
Consider the system of linear equations above. What is the value of $6x$?', '["$\\frac{7}{2}$", "$7$", "$14$", "$21$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
