insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('e031435d-0d32-51c0-b4d8-359c63a73cb4', 0, null, 'The diagonal of an inscribed rectangle is a diameter, so the radius is $\frac{482\sqrt{3}}{2} = 241\sqrt{3}$.'),
  ('c74e8f33-98c5-5bc2-a085-c4365715314f', 3, null, 'For $x^{2} + bx + c = 0$ the sum of the solutions is $-b = 90$.'),
  ('f9f28697-c6a8-571d-a602-d6df59c6ad17', 2, null, '$g(0) = \frac{f(0)}{4} = 54$, so $f(0) = 216$.'),
  ('1944b6c7-5b45-5095-937a-fd6487fb0431', 2, null, '$V = \frac{1}{3}a^{2}h = \frac{1}{3}(16)(6) = 32$.'),
  ('fc8abd56-bf98-55aa-9a28-63ceb901e01a', 2, null, 'An upward parabola whose vertex is below $y = -9$ crosses that line twice.'),
  ('701d658f-d08c-5a56-9389-b8204a604807', 2, null, '$(x - 4)^{2} = 100$, so $x - 4 = 10$ and $x = 14$ (positive).'),
  ('174e0989-26e1-5743-b095-6cef1a136cf0', 1, null, 'Line $j$ is the $x$-axis, so line $k$ is the $y$-axis ($x = 0$); they meet at $x = 0$.'),
  ('9da719bf-0007-508f-b24d-31a9ea87c39d', 0, null, '$f(0) = 0 + 3 = 3$ and $f(8) = 8(0) + 3 = 3$.'),
  ('7eac25d0-ca9e-587a-90d9-d39500b05a65', 0, null, '$\overline{ED} \perp \overline{AC}$, so $\overline{ED} \parallel \overline{BC}$ and triangle $AED$ is similar to triangle $ACB$ with ratio $\frac{AE}{AC} = \frac{1}{3}$. $ED = \frac{198}{3} = 66$.'),
  ('40613a85-970f-57c3-b863-fe7b400d8f48', 1, null, '$f(270) = 16 - \frac{270}{27} = 16 - 10 = 6$.'),
  ('12078bec-569c-5682-87d0-e309725004cb', 0, null, '$6 = -4x + 2$ gives $x = -1$, so the solution is $(-1, 6)$.'),
  ('7e016b56-3012-5ad8-a221-b5b523c7ddc4', 2, null, 'At $t = 0$ the remaining distance is $22$: the total distance of the run.'),
  ('6740f591-5655-5bf0-9c12-fbdebb80e197', 3, null, 'Each 5 seconds the value is multiplied by $0.8$: $f(x) = 340(0.8)^{\frac{x}{5}}$.'),
  ('5a19c1ac-11af-5037-ac93-c73eb79d0ab9', 0, null, '$y = (1.12)(1.04)$: the two growth factors multiply.'),
  ('5c2a6441-232f-5ebd-a45d-37a54c8fd6f4', 1, null, 'Each $y$ is $0.6$ times the previous one, a constant ratio below 1: exponential decay.'),
  ('c916faa5-2398-5d3f-89f5-cbee71f47f0a', 1, null, '$31,152 \div 36 ≈ 865.33$ yards per hour.'),
  ('468765f6-7954-59eb-93ff-e05fac82da20', 0, null, 'At $x = 5$ the line gives about $6$ and the data point is at $5$: a difference of $1$.'),
  ('a61c327c-de18-56cf-b5ff-eed0f420878c', 2, null, '$g(0) = -\sqrt{c} = -\sqrt{298}$ gives $c = 298$; $g(2) = 0$ gives $4 + 2b + 298 = 0$, so $b = -151$. $x^{2} - 151x + 298 = (x - 2)(x - 149)$, so the greatest zero is $149$.'),
  ('144a2855-d23b-5d59-a6c2-fbaa877ea12d', 0, null, '$18p - 19p = -p = 17$, so $p = -17$.'),
  ('be2c37c4-c960-53d7-9317-5bdbe05d3caf', 1, null, 'Both are radii of the same circle: $34$ mm.'),
  ('0575fb67-9b8e-53ad-aeaa-3678ad1b3889', 1, null, '$\frac{4(x - 5) - 4}{(x - 5)^{2}} = \frac{4x - 24}{(x - 5)^{2}}$.'),
  ('f8c135ce-5b10-5b74-9dda-e0f2f53ec6ad', 1, null, 'Adding the equations gives $0 = -3 + 16y$, so $y = \frac{3}{16}$ and $3x = 2 + \frac{3}{2} = \frac{7}{2}$. Then $6x = 7$.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
